   371	
   372	    const pusherChannelName = getReportChannelName(reportID);
   373	    Pusher.subscribe(pusherChannelName, Pusher.TYPE.USER_IS_LEAVING_ROOM, (leavingStatus: Pusher.UserIsLeavingRoomEvent) => {
   374	        // If the pusher message comes from OldDot, we expect the leaving status to be keyed by user
   375	        // login OR by 'Concierge'. If the pusher message comes from NewDot, it is keyed by accountID
   376	        // since personal details are keyed by accountID.
   377	        const normalizedLeavingStatus = getNormalizedStatus(leavingStatus);
   378	        const accountIDOrLogin = Object.keys(normalizedLeavingStatus).at(0);
